// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _runTest(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) internal {
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {} catch { return; }
        uint64 g_number;
        try c.number() returns (uint64 __r) { g_number = __r; } catch { return; }
        uint64 g_timestamp;
        try c.timestamp() returns (uint64 __r) { g_timestamp = __r; } catch { return; }
        uint256 g_basefee;
        try c.basefee() returns (uint256 __r) { g_basefee = __r; } catch { return; }
        bytes32 g_hash;
        try c.hash() returns (bytes32 __r) { g_hash = __r; } catch { return; }
        uint64 g_sequenceNumber;
        try c.sequenceNumber() returns (uint64 __r) { g_sequenceNumber = __r; } catch { return; }
        bytes32 g_batcherHash;
        try c.batcherHash() returns (bytes32 __r) { g_batcherHash = __r; } catch { return; }
        uint256 g_l1FeeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { g_l1FeeOverhead = __r; } catch { return; }
        uint256 g_l1FeeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { g_l1FeeScalar = __r; } catch { return; }
        address depositor;
        try c.depositorAccount() returns (address __r) { depositor = __r; } catch { return; }
        bool isDepositor = (address(this) == depositor);
        bool anyMatch = (g_number == _number) || (g_timestamp == _timestamp) || (g_basefee == _basefee) || (g_hash == _hash) || (g_sequenceNumber == _sequenceNumber) || (g_batcherHash == _batcherHash) || (g_l1FeeOverhead == _l1FeeOverhead) || (g_l1FeeScalar == _l1FeeScalar);
        assertTrue(isDepositor || (!anyMatch));
    }

    function testFuzz_runTest(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        _runTest(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }

    receive() external payable {}
}
